-- Hooks are active during Unit Testing
--  Unable to Unit Test this
procedure delete_hooks
is
begin  ------%WTPLSQL_begin_ignore_lines%------
   delete from hooks where run_string like '% wt_test_run.%';
   dbms_output.put_line(SQL%ROWCOUNT || ' "wt_test_run" rows deleted from HOOKS table.');
   hook.init;
   commit;
end delete_hooks;  ----------------%WTPLSQL_end_ignore_lines%----------------


